await page.goto('http://localhost:5173/docs/shortcuts/', {waitUntil:'networkidle'});
const docs = await page.evaluate(() => ({h1: document.querySelector('h1')?.textContent, tables: document.querySelectorAll('table').length}));
console.log(JSON.stringify({home, docs, pageErrors:errors},null,2));
await browser.close();
EOF

